   {
      if(OrderSelect(i, SELECT_BY_POSITION, false))
      {
         if(op == OP_BUY && OrderType() == OP_BUY && OrderPosition() >= 0) return true;
         if(op == OP_SELL && OrderType() == OP_SELL && OrderPosition() < 0) return true;
         DeselectOrder();
      }
   }
   return false;
}

