//+=================================================================+
//|                                                               JacssonMT4.mq4|
//|                        Robô de sinal Cruzamento EMA-45          |
//+------------------------------------------------------------------+
#property strict

//------------------------------- Entradas ----------------------------+
input double Lots                = 0.1;               // Lote (ex.: 0.1 = micro lote ouro)
input int    EMA_Period          = 45;                // Período da EMA
input double RiskRewardRatio     = 2.0;               // R:R (ex.: 2.0 = ganha 2 pra cada 1 perdido)
input long   SL_Points           = 150;              // Stop em pontos (recomendado pro XAUUSD; pips variam muito no ouro)
input int    Slippage            = 30;               // Slippagem máxima em pontos (padrão ouro)
input uint   MagicNumber         = 0;                // Número mágico (deixe 0 ou defina seu)

//------------------------------- Constantes -------------------------+
const string TAG_EMA = "EMA_";
const color  EMA_COLOR   = clrBlue;
const int    EMA_WIDTH   = 2;

//+------------------------------------------------------------------+
//| Cria uma única série visual da EMA no gráfico                    |
//+------------------------------------------------------------------+
int CreateEMAIndicator()
{
   double *buf = ArrayResize(new double[Bars + EMA_Period], 0.0);
   // (buffer opcional para uso interno; não necessário aqui)

   int hs = CustomIndicatorFunctions::CreateSeries(
      TAG_EMA + IntegerToString(EMA_Period),
      true,                                   // visível
      0.0,                                   // valor inicial
      MODE_BARS,                             // desenhar nos limites das velas
      -1,                                    // profundidade de histórico = toda a série
      EMA_COLOR,                             // cor azul
      STYLE_SOLID,                           // estilo sólido
      EMA_WIDTH,                             // largura da linha
      0.0, 0.0                               // desvio mín/máx (irrelevante aqui)
   );

   if(hs < 0)
   {
      Print("Falha ao criar o indicador da EMA:", GetLastError());
      return -1;
   }

   CustomIndicatorFunctions::SetString(hs, sIndStyle,        STYLE_SOLID);
   CustomIndicatorFunctions::SetString(hs, sIndColor,       EMA_COLOR);
   CustomIndicatorFunctions::SetInteger(hs, sLineWidth,    EMA_WIDTH);
   CustomIndicatorFunctions::SymbolName(hs, _Symbol);      // ajusta símbolo da série
   CustomIndicatorFunctions::SetString(hs, sIndLabel,       TAG_EMA + IntegerToString(EMA_Period));

   return(hs);
}
```

