```mq4
//+=================================================================+
//|                                                             JacssonMT4.mq4|
//|                          Cruzamento EMA-45 (uma linha azul)      |
//+------------------------------------------------------------------+
#property strict

#include <CustomIndicatorFunctions.mqh>   // necessario para criar a serie da EMA

// --------------------------- Entradas -----------------------------+
input double Lots                   = 0.1;     // Lote
input int    EMA_Period             = 45;     // Periodo da EMA
input double RiskRewardRatio        = 2.0;    // R:R
input long   SL_Points              = 150;    // Parada em pontos (recomendado p/ ouro)
input int    Slippage               = 30;     // Slippage em pontos
input uint   MagicNumber            = 0;      // (opcional) Numero magico

// ----------------------- Constantes visuais ------------------------+
const string TAG_EMA = "EMA_";
const color  EMA_COL  = clrBlue;
const int    EW       = 2;

//+------------------------------------------------------------------+
//| Cria a LINHA unica da EMA no grafo                                |
//+------------------------------------------------------------------+
int CreateEMASeries()
{
   double *tmp = ArrayResize(new double[Bars + EMA_Period], 0.0); // buffer inutil aqui; mantido p/ clareza

   int h = CustomIndicatorFunctions::CreateSeries(
      TAG_EMA + IntegerToString(EMA_Period),
      true, 0.0,                         // visivel, valor inicial
      MODE_BARS, -1,                     // plota nos bordos das velas; historia total
      EMA_COL,                           // cor azul
      STYLE_SOLID, EW,                   // estilo solido, largura
      0.0, 0.0
   );
   if(h < 0) return -1;

   CustomIndicatorFunctions::SetString(h, sIndStyle,        STYLE_SOLID);
   CustomIndicatorFunctions::SetString(h, sIndColor,       EMA_COL);
   CustomIndicatorFunctions::SetInteger(h, sLineWidth,    EW);
   CustomIndicatorFunctions::SymbolName(h, _Symbol);
   CustomIndicatorFunctions::SetString(h, sIndLabel,       TAG_EMA + IntegerToString(EMA_Period));

   return h;
}
