void OnTick()
{
   if(Symbol() != "XAUUSD") return;

   // valor atual da EMA (usada so para a logica de sinal)
   double ema = iMA(Symbol(), (int)MarketInfo(_IndexFigSizeInDigits()),
                    EMA_Period, 0, MODE_EMA, MODE_SMTH, PRICE_CLOSE);
   if(ema < 0) return;        // dado invalido

   double entry = EntryPrice();
   double dist  = SL_Points;  // distancia da parada em pontos do grafico

   // ----- COMPRA -----
   if(CheckBuySignal(ema) && !IsOrderActive(OP_BUY))
   {
      double sl = entry - dist;
      double tp = entry + dist * RiskRewardRatio;

      int ticket = OrderSend(_Symbol, OP_BUY, Lots, Ask, Slippage,
                             sl, tp, "Compra automática - "+_PeriodName(),
                             0, (long)MagicNumber, clrGreen, "Sinal EMA");
      if(ticket < 0)
         Print("Falha na compra. Erro: ", GetLastError());
      else
         Print("Compra aberta: ticket ", ticket, "| SL ", DoubleToString(sl, MarketInfo(_IndexFigSizeInDigits())),
               "| TP ", DoubleToString(tp, MarketInfo(_IndexFigSizeInDigits())));
   }

   // ----- VENDA -----
   if(CheckSellSignal(ema) && !IsOrderActive(OP_SELL))
   {
      double sl = entry + dist;
      double tp = entry - dist * RiskRewardRatio;

      int ticket = OrderSend(_Symbol, OP_SELL, Lots, Bid, Slippage,
                             sl, tp, "Venda automatica - "+_PeriodName(),
                             0, (long)MagicNumber, clrRed, "Sinal EMA");
      if(ticket < 0)
         Print("Falha na venda. Erro: ", GetLastError());
      else
         Print("Venda aberta: ticket ", ticket, "| SL ", DoubleToString(sl, MarketInfo(_IndexFigSizeInDigits())),
               "| TP ", DoubleToString(tp, MarketInfo(_IndexFigSizeInDigits())));
   }
}
