//+------------------------------------------------------------------+
//| Valor da EMA num determinado instante                            |
//+------------------------------------------------------------------+
double GetEMA(double t)
{
   double v = iMA(NULL, 0, EMA_Period, 0, MODE_EMA, MODE_SMTH, PRICE_CLOSE, (int)t);
   return (v > 0) ? v[0] : 0.0;
}

