//| Desenha a EMA manualmente (para casos sem CustomIndicatorFn)     |
//+------------------------------------------------------------------+
void DrawEMA()
{
   if(StringCompare(Symbol(),"XAUUSD") != 0) return;
   if(AccountEmpty()) return;

   // ultima vela fechada
   ulong b0 = iLow(NULL, 0, 0, TIME_NEXTBARTIME, MODE_TIME);
   if(b0 == INVALID_U64) return;
   if(b0 >= Bars) return;

   // intervalo da barra em ms
   ulong dur = (ulong)iPeriodsInterval() * 3600;
   if(dur <= 0) return;

   // abrangencia de 2 velas p/ calcular faixa de desenho
   ulong b2 = b0 + 2 * dur;

   // faixa vertical
   ulong loIdx = iLow(NULL, 0, b0, b2, 0);
   ulong hiIdx = iHigh(NULL, 0, b0, b2, 0);
   double yMin = iLow(NULL, 0, loIdx, 0);
   double yMax = iHigh(NULL, 0, hiIdx, 0);
   double rng  = MathMax(yMax - yMin, 1.0);
   double yBot = MathMin(yMin, yMax - rng * 0.02);   // margem inferior
   double yTop = yMax + rng * 0.02;                   // margem superior

   int nSub = 48;          // pontos na linha
   int nb   = (int)MathAbs((b2 - b0) / dur);
   if(nb < 2) nb = 2;
   int q = MathMax(3, nSub / MathMax(nb, 1)); // subdivisoes por barra

   vector<string>  xs;
   vector<double>  ys;
   xs.Resize(nSub); ys.Resize(nSub);

   for(int k = 0; k <= nb; k++)
   {
