//+=================================================================+
//|                                                              JacssonMT4.mq4|
//|                       Robot: sinais no cruzamento da EMA-45     |
//+------------------------------------------------------------------+
#property strict

#include <CustomIndicatorFunctions.mqh>   // necessario p/ inserir a linha da EMA

// ------------------------------------------------------------------+
//| Parâmetros                                                        |
//+------------------------------------------------------------------+
input double Lots                 = 0.1;   // Lote utilizado
input int    EMA_Period           = 45;    // Periodo da EMA
input double RiskRewardRatio      = 2.0;   // Relacao R:R desejada
input long   SL_Points            = 150;   // Distancia do Stop em pontos (XAUUSD)
input int    Slippage             = 30;    // Slippagem maxima permitida (pontos)
input uint   MagicNumber          = 0;     // Num.magico da conta (0 = sem filtro)

// ------------------------------------------------------------------+
//| Constantes do desenho da linha                                   |
//+------------------------------------------------------------------+
const string TAG_EMA = "EMA_";
const color  COL_EMA = clrBlue;
const int    W_LARG  = 2;

//+------------------------------------------------------------------+
//| Cria UMA unica linha azul da EMA-45 no grafico                    |
//+------------------------------------------------------------------+
int CreateEMASeries()
{
   int h = CustomIndicatorFunctions::CreateSeries(
      TAG_EMA + IntegerToString(EMA_Period),      // nome: "EMA_45"
      true,                                        // visivel
      0.0,                                         // valor inicial
      MODE_BARS,                                   // desenha nos limites das velas
      -1,                                          // serie com toda a historia disponivel
      COL_EMA,                                     // cor azul
      STYLE_SOLID, W_LARG,                         // estilo solido, largura 2
      0.0, 0.0                                     // desvios (nao utilizados)
   );

   if(h < 0)
   {
      Print("Falha ao criar a linha da EMA:", GetLastError());
      return(-1);
   }

   // configura a formula como EMA e o periodo
   CustomIndicatorFunctions::SetString(h, sIndMethod, MODE_EMA);
   CustomIndicatorFunctions::SetInteger(h, sIndPeriod, EMA_Period);
   CustomIndicatorFunctions::SetString(h, sIndColor, COL_EMA);
   CustomIndicatorFunctions::SetInteger(h, sLineWidth, W_LARG);
   CustomIndicatorFunctions::SetString(h, sIndLabel, TAG_EMA + IntegerToString(EMA_Period));
   CustomIndicatorFunctions::SetString(h, sIndArrowDrawingMode, "");  // evita setas desnecessarias

   return(h);
}

//+------------------------------------------------------------------+
//| Remove linhas manuais antigas da EMA (execucoes anteriores)       |
//+------------------------------------------------------------------+
void DeleteOldLines()
{
   int removidas = 0;
   for(int i = 0; i < ElementsCount(); i++)
   {
      if(StringFind(ObjectName(i), TAG_ESA) < 0 || ObjectType(i) != OBJ_TREND) continue;
      // typo careful: TAG_ESA vs TAG_EMA! Must be TAG_EMA.
      ObjectDelete(0, ObjectName(i));
      ObjectDestroy(i);
      removidas++;
   }
   if(removidas > 0)
      Print("Limpeza: removidas ", removidas, " linha(s) antiga(s) da EMA.");
}
