void OnTick()
{
   if(StringCompare(Symbol(), "XAUUSD") != 0) return;

   // valor atual da EMA (utilizado apenas na logica de sinal)
   double ema = iMA(Symbol(), NULL, EMA_Period, 0, MODE_EMA, MODE_SMTH, PRICE_CLOSE);
   if(ema < 0) return;   // historico insuficiente / dado invalido

   double entrada = EntryPrice();
   double dist    = SL_Points;  // distancia do stop medida em pontos

   // garante que nunca haja mais de uma posicao ativa por vez
   if(TemPosicaoAberta()) return;

   // -------- COMPRA --------
   if(CheckBuySignal(ema) && !IsOrderActive(OP_BUY))
   {
      double sl = entrada - dist;       // stop abaixo da entrada
      double tp = entrada + dist * RiskRewardRatio; // alvo acima da entrada

      int ticket = OrderSend(_Symbol, OP_BUY, Lots, Ask, Slippage,
                             sl, tp, "Compra - Sinal EMA",
                             0, (long)MagicNumber, clrGreen);
      if(ticket < 0)
         Print("Falha na compra. Erro: ", GetLastError());
