//+------------------------------------------------------------------+
//| Verifica se ha ordem ativa do tipo 'op'                          |
//+------------------------------------------------------------------+
bool IsOrderActive(ENUM_OP op)
{
   for(int i = 0; i < OrdersTotal(); i++)
   {
      if(OrderSelect(i, SELECT_BY_POSITION, false))
      {
         if(op == OP_BUY && OrderType() == OP_BUY && OrderPosition() >= 0)
            return true;
         if(op == OP_SELL && OrderType() == OP_SELL && OrderPosition() < 0)
            return true;
         DeselectOrder();
      }
   }
   return false;
}

//+------------------------------------------------------------------+
//| Compra: preco cruzou para ACIMA da EMA (cenario bullish)          |
//+------------------------------------------------------------------+
bool CheckBuySignal(double ema)
{
   // vela anterior fechou ABAIXO da EMA e agora fechou ACIMA dela
   if(Close[1] < ema && Close[0] > ema) return true;
   // impede novo sinal enquanto o preco seguir abaixo da EMA
   if(Close[0] < ema) return false;
   return false;
}

//+------------------------------------------------------------------+
//| Venda: preco cruzou para BAIXO da EMA (cenario bearish)           |
//+------------------------------------------------------------------+
bool CheckSellSignal(double ema)
{
   if(Close[1] > ema && Close[0] < ema) return true;
   if(Close[0] > ema) return false;
   return false;
}
